from __future__ import annotations

import struct
import sys
import xml.etree.ElementTree as ET
from pathlib import Path

import pytest
import typer
from ds.cli import ui_service
from ds.cli.ui_service import FAVICON, Systemd, WindowsTask, png_to_ico, service, task_xml

NS = {"t": "http://schemas.microsoft.com/windows/2004/02/mit/task"}


def test_service_is_picked_by_platform(monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.setattr(sys, "platform", "linux")
    assert isinstance(service(), Systemd)
    monkeypatch.setattr(sys, "platform", "win32")
    assert isinstance(service(), WindowsTask)


def test_install_is_refused_on_omarchy() -> None:
    # the unit comes from `os sync` there
    with pytest.raises(typer.Exit):
        Systemd().install()


def _task(**overrides: str) -> ET.Element:
    values = {"command": r"C:\repo\.venv\Scripts\pythonw.exe", "arguments": "-m ds.cli ui run"}
    values |= {"workdir": r"C:\repo", "user": r"DESKTOP\kd"} | overrides
    # schtasks reads it as UTF-16; ElementTree wants bytes for a document with a declaration
    return ET.fromstring(task_xml(**values).encode("utf-16"))  # noqa: S314  # our own XML


def test_task_runs_at_this_users_logon_without_admin() -> None:
    task = _task()
    assert task.findtext("t:Triggers/t:LogonTrigger/t:UserId", namespaces=NS) == r"DESKTOP\kd"
    principal = task.find("t:Principals/t:Principal", NS)
    assert principal is not None
    assert principal.findtext("t:LogonType", namespaces=NS) == "InteractiveToken"
    assert principal.findtext("t:RunLevel", namespaces=NS) == "LeastPrivilege"


def test_task_restarts_on_failure_and_never_times_out() -> None:
    settings = _task().find("t:Settings", NS)
    assert settings is not None
    assert settings.findtext("t:RestartOnFailure/t:Count", namespaces=NS) == "3"
    assert settings.findtext("t:ExecutionTimeLimit", namespaces=NS) == "PT0S"
    assert settings.findtext("t:MultipleInstancesPolicy", namespaces=NS) == "IgnoreNew"


def test_task_values_are_escaped() -> None:
    # a folder like "C:\Smash & Co" must not break the XML
    task = _task(workdir=r"C:\Smash & Co")
    assert task.findtext("t:Actions/t:Exec/t:WorkingDirectory", namespaces=NS) == r"C:\Smash & Co"


def test_ico_wraps_the_favicon() -> None:
    png = FAVICON.read_bytes()
    ico = png_to_ico(png)
    reserved, kind, count = struct.unpack("<HHH", ico[:6])
    width, height, _, _, _, bits, size, offset = struct.unpack("<BBBBHHII", ico[6:22])
    assert (reserved, kind, count) == (0, 1, 1)
    assert (width, height, bits) == (64, 64, 32)
    assert (size, offset) == (len(png), 22)
    assert ico[offset:] == png


def test_logs_prints_the_last_lines(
    monkeypatch: pytest.MonkeyPatch, tmp_path: Path, capsys: pytest.CaptureFixture[str]
) -> None:
    monkeypatch.setenv("LOCALAPPDATA", str(tmp_path))
    log = ui_service.log_file()
    log.parent.mkdir(parents=True)
    log.write_text("".join(f"line {n}\n" for n in range(10)), encoding="utf-8")
    WindowsTask().logs(lines=3, follow=False)
    assert capsys.readouterr().out == "line 7\nline 8\nline 9\n"


def test_logs_before_any_run(
    monkeypatch: pytest.MonkeyPatch, tmp_path: Path, capsys: pytest.CaptureFixture[str]
) -> None:
    monkeypatch.setenv("LOCALAPPDATA", str(tmp_path))
    WindowsTask().logs(lines=3, follow=False)
    assert "No log yet" in capsys.readouterr().out


def test_serve_writes_the_log_and_keeps_the_previous_run(tmp_path: Path) -> None:
    log = tmp_path / "ui.log"
    log.write_text("old run\n", encoding="utf-8")
    code = ui_service.serve([sys.executable, "-c", "print('✓ up')"], tmp_path, log)
    assert code == 0
    assert log.read_text(encoding="utf-8") == "✓ up\n"
    assert log.with_suffix(".previous.log").read_text(encoding="utf-8") == "old run\n"
